mapper.select:
SELECT pr.payment_id AS paymentId, pr.payment_no AS paymentNo, pr.bill_id AS billId, pr.owner_id AS ownerId, pr.owner_name AS ownerName, pr.room_id AS roomId, pr.payment_amount AS paymentAmount, pr.payment_method AS paymentMethod, pr.payment_status AS paymentStatus, pr.payment_time AS paymentTime, pr.operator_name AS operatorName, pr.receipt_no AS receiptNo, pr.create_by AS createBy, pr.create_time AS createTime, pr.update_by AS updateBy, pr.update_time AS updateTime, pr.remark AS remark, fb.bill_no AS billNo, fb.item_name AS itemName, c.community_name AS communityName, b.building_name AS buildingName, u.unit_name AS unitName, r.room_name AS roomName, o.owner_real_name AS ownerRealName, o.owner_phone_number AS ownerPhoneNumber FROM community_payment_record pr LEFT JOIN community_fee_bill fb ON fb.bill_id = pr.bill_id LEFT JOIN owner o ON o.owner_id = pr.owner_id LEFT JOIN room r ON r.room_id = pr.room_id LEFT JOIN community c ON c.community_id = r.community_id LEFT JOIN building b ON b.building_id = r.building_id LEFT JOIN unit u ON u.unit_id = r.unit_id
AND c.community_id = #{q.communityId}
AND pr.payment_no LIKE CONCAT('%', #{q.paymentNo}, '%')
AND fb.bill_no LIKE CONCAT('%', #{q.billNo}, '%')
AND pr.bill_id = #{q.billId}
AND pr.owner_id = #{q.ownerId}
AND (pr.owner_name LIKE CONCAT('%', #{q.ownerName}, '%') OR o.owner_real_name LIKE CONCAT('%', #{q.ownerName}, '%'))
AND pr.room_id = #{q.roomId}
AND pr.payment_method = #{q.paymentMethod}
AND pr.payment_status = #{q.paymentStatus}
AND pr.receipt_no LIKE CONCAT('%', #{q.receiptNo}, '%')
ORDER BY pr.payment_time DESC, pr.payment_id DESC
